		public enum DirectionType {			[Description("Half of litre")]			Vertical,			[Description("One litre")]			Horizontal,		}		[TypeConverter(typeof(DrinkDosesConverter))]		public DirectionType SpinnDirection { get => spinnDirection; set => spinnDirection = value; }class DrinkDosesConverter:EnumConverter {	private readonly Type _enumType;	public DrinkDosesConverter(Type type): base(type) {_enumType = type;}	public override bool CanConvertTo(ITypeDescriptorContext context, Type destType) {		return destType == typeof(string);	}	public override object ConvertTo(ITypeDescriptorContext context, CultureInfo culture, object value, Type destType) {		FieldInfo fi = _enumType.GetField(Enum.GetName(_enumType, value));		DescriptionAttribute dna =(DescriptionAttribute)Attribute.GetCustomAttribute(fi, typeof(DescriptionAttribute));		if (dna != null)			return dna.Description;		else			return value.ToString();	}	public override bool CanConvertFrom(ITypeDescriptorContext context, Type srcType) {		return srcType == typeof(string);	}	public override object ConvertFrom(ITypeDescriptorContext context, CultureInfo culture, object value) {		foreach (FieldInfo fi in _enumType.GetFields()) {			DescriptionAttribute dna =		(DescriptionAttribute)Attribute.GetCustomAttribute(fi, typeof(DescriptionAttribute));			if ((dna != null) && ((string)value == dna.Description))				return Enum.Parse(_enumType, fi.Name);		}		return Enum.Parse(_enumType, (string)value);	}}// Or with imagesclass GameValuesConverter : EnumConverter{    private Type _enumType;     public GameValuesConverter(Type type)        : base(type)    {        _enumType = type;    }     public override bool CanConvertTo(ITypeDescriptorContext context,    Type destType)    {        return destType == typeof(string);    }     public override object ConvertTo(ITypeDescriptorContext context,    CultureInfo culture,    object value, Type destType)    {        FieldInfo fi = _enumType.GetField(Enum.GetName(_enumType, value));        DescriptionAttribute dna =        (DescriptionAttribute)Attribute.GetCustomAttribute(        fi, typeof(DescriptionAttribute));         if (dna != null)            return dna.Description;        else            return value.ToString();    }     public override bool CanConvertFrom(ITypeDescriptorContext context,    Type srcType)    {        return srcType == typeof(string);    }     public override object ConvertFrom(ITypeDescriptorContext context,    CultureInfo culture,    object value)    {        foreach (FieldInfo fi in _enumType.GetFields())        {            DescriptionAttribute dna =            (DescriptionAttribute)Attribute.GetCustomAttribute(            fi, typeof(DescriptionAttribute));             if ((dna != null) && ((string)value == dna.Description))                return Enum.Parse(_enumType, fi.Name);        }         return Enum.Parse(_enumType, (string)value);    }}class GameEditor : UITypeEditor{    public override bool GetPaintValueSupported(ITypeDescriptorContext context)    {        return true;    }    public override void PaintValue(PaintValueEventArgs e)    {        string whatImage = e.Value.ToString();        whatImage += ".bmp";        //getting picture        Bitmap bmp = (Bitmap)Bitmap.FromFile(whatImage);        Rectangle destRect = e.Bounds;        bmp.MakeTransparent();         //and drawing it        e.Graphics.DrawImage(bmp, destRect);    }}and then Bind it using Editor attribute to make it an editable field:class GameClassDisplayer{    GameValues m_GameValues;    [DisplayName("Choose your variant")]    [Description("You can choose between Stone, scissors, paper")]    [Category("Choosing")]    [Editor(typeof(GameEditor), typeof(UITypeEditor))]    public GameValues DisplayGameValues    {        get        {            return 